// Replays the golden fixtures generated by the Kotlin app (app/src/test/.../GoldenFixturesTest.kt):
// every stored list, active session and backup file must decode and re-encode exactly as Kotlin does.
import { describe, expect, test } from 'bun:test';
import { decodeBackup, encodeBackup } from '../backup';
import { parseKJson, stringifyKJson } from '../kjson';
import {
  decodeChantState,
  decodeGoal,
  decodeSessionRecord,
  encodeChantState,
  encodeGoal,
  encodeSessionRecord,
  increment,
  normalizedRounds,
  toRecord,
} from '../model';
import { decodeStoredList, encodeStoredList, withUniqueGoalIds, withUniqueRecordIds } from '../storedList';
import golden from '../__fixtures__/golden.json';

type Case =
  | { name: string; kind: 'counter'; input: string; presses: number; accepted: number; output: string; events: string[]; record: string }
  | { name: string; kind: 'history' | 'goals'; input: string | null; items: string[]; unreadable: string[]; corrupt: boolean; rewritten: string }
  | { name: string; kind: 'activeSession' | 'backup'; input: string; output: string | null; error: string | null };

const cases = golden as Case[];

describe('golden fixtures from the Kotlin app', () => {
  for (const c of cases) {
    test(`${c.kind}: ${c.name}`, () => {
      if (c.kind === 'history') {
        const list = decodeStoredList(decodeSessionRecord, c.input);
        const items = withUniqueRecordIds(list.items);
        expect(items.map((r) => stringifyKJson(encodeSessionRecord(r)))).toEqual(c.items);
        expect(list.unreadable.map(stringifyKJson)).toEqual(c.unreadable);
        expect(list.corrupt).toBe(c.corrupt);
        expect(encodeStoredList(encodeSessionRecord, items, list.unreadable)).toBe(c.rewritten);
      } else if (c.kind === 'goals') {
        const list = decodeStoredList(decodeGoal, c.input);
        const items = withUniqueGoalIds(list.items);
        expect(items.map((g) => stringifyKJson(encodeGoal(g)))).toEqual(c.items);
        expect(list.unreadable.map(stringifyKJson)).toEqual(c.unreadable);
        expect(list.corrupt).toBe(c.corrupt);
        expect(encodeStoredList(encodeGoal, items, list.unreadable)).toBe(c.rewritten);
      } else if (c.kind === 'activeSession') {
        let output: string | null = null;
        let error: string | null = null;
        try {
          output = stringifyKJson(encodeChantState(normalizedRounds(decodeChantState(parseKJson(c.input)))));
        } catch (e) {
          error = (e as Error).constructor.name;
        }
        expect(output).toBe(c.output);
        expect(error != null).toBe(c.error != null);
      } else if (c.kind === 'counter') {
        let state = decodeChantState(parseKJson(c.input));
        const events: string[] = [];
        let accepted = 0;
        for (let i = 1; i <= c.presses; i++) {
          const r = increment(state);
          if (!r) continue;
          state = r.state;
          accepted++;
          if (r.feedback !== 'COUNT') events.push(`${i}:${r.feedback}`);
        }
        expect(accepted).toBe(c.accepted);
        expect(events).toEqual(c.events);
        expect(stringifyKJson(encodeChantState(state))).toBe(c.output);
        expect(stringifyKJson(encodeSessionRecord(toRecord(state, state.sessionStartTime + 60_000)))).toBe(c.record);
      } else if (c.kind === 'backup') {
        let output: string | null = null;
        let error: string | null = null;
        try {
          output = encodeBackup(decodeBackup(c.input));
        } catch (e) {
          error = (e as Error).constructor.name;
        }
        expect(output).toBe(c.output);
        expect(error).toBe(c.error == null ? null : 'BackupFormatException');
      }
    });
  }
});
